:root {
  /* Colors */
  --color-fog-canvas: #f5f5f5;
  --color-paper-tile: #ffffff;
  --color-carbon-panel: #1f1f1f;
  --color-ink: #000000;
  --color-slate-caption: #4a5565;
  --color-ash-caption: #8a8a8a;
  --color-pewter-border: #d1d5dc;
  --color-ember-signal: #e42b0c;
  --color-ember-flare: #ff6a13;

  /* Typography — Font Families */
  --font-telegraf: "Telegraf", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-modern-gothic: "modernGothic", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0.3px;
  --text-caption: 14px;
  --leading-caption: 1.43;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.625;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.333;
  --tracking-subheading: -0.72px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.333;
  --tracking-heading-sm: -0.6px;
  --text-heading: 30px;
  --leading-heading: 1.2;
  --tracking-heading: -0.75px;
  --text-heading-lg: 60px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -1.5px;
  --text-display: 72px;
  --leading-display: 1;
  --tracking-display: -2.16px;

  /* Typography — Weights */
  --font-weight-thin: 100;
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;

  /* Layout */
  --layout-max-width: 1440px;
  --layout-content-width: 1280px;
  --layout-section-gap: 8px;
  --layout-card-padding: 32px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;

  /* Named Radii */
  --radius-cards: 8px;
  --radius-sections: 8px;
  --radius-images: 8px;
  --radius-buttons: 6px;
  --radius-nav: 6px;
  --radius-inner-tiles: 6px;
  --radius-inputs: 4px;
  --radius-small-elements: 4px;

  /* Shadows */
  --shadow-sm: 0px 1px 3px 0px rgba(0, 0, 0, 0.1), 0px 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-sm-2: inset 0px 0px 20px 0px rgba(243, 43, 9, 0.4);

  /* Surfaces */
  --surface-fog-canvas: #f5f5f5;
  --surface-paper-tile: #ffffff;
  --surface-carbon-panel: #1f1f1f;
  --surface-ink: #000000;
}

